// Project Diagnostics feature module. Validated runtime configuration.
namespace ClearGameEngine.RootFeatures;
public sealed class ProjectDiagnosticsFeature:FeatureModuleBase{public const string FeatureId="project-diagnostics";public ProjectDiagnosticsFeature():base(FeatureId,"Project Diagnostics",new FeatureSetting("budget","Project Diagnostics budget",768,1,100000),new FeatureSetting("quality","Quality level",2,0,4)){} public int Budget{get=>TryGet("budget",out var v)?(int)v:768;set=>TrySet("budget",value);} public int Quality{get=>TryGet("quality",out var v)?(int)v:2;set=>TrySet("quality",value);} public bool IsConfigured=>Validate(out _);}
